selector_to_html = {"a[href=\"#see-also\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">See Also<a class=\"headerlink\" href=\"#see-also\" title=\"Link to this heading\">#</a></h2>", "a[href=\"user_guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>For</p>", "a[href=\"#cellpose-input-images\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Cellpose Input Images<a class=\"headerlink\" href=\"#cellpose-input-images\" title=\"Link to this heading\">#</a></h2><p>Cellpose segments one static image, chosen by <code class=\"docutils literal notranslate\"><span class=\"pre\">cellpose_settings.img</span></code>. Suite2p 1.1.0 accepts three values:</p>", "a[href=\"#processing-pipeline\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Processing Pipeline<a class=\"headerlink\" href=\"#processing-pipeline\" title=\"Link to this heading\">#</a></h2><p>Images stored in <code class=\"docutils literal notranslate\"><span class=\"pre\">ops.npy</span></code> are computed at different stages:</p>", "a[href=\"#spatial-high-pass-filter\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Spatial High-Pass Filter<a class=\"headerlink\" href=\"#spatial-high-pass-filter\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">spatial_hp_cp</span></code> (upstream <code class=\"docutils literal notranslate\"><span class=\"pre\">cellpose_settings.highpass_spatial</span></code>; integer, default 0) sharpens the chosen <code class=\"docutils literal notranslate\"><span class=\"pre\">img</span></code> before Cellpose. It is separate from the temporal <code class=\"docutils literal notranslate\"><span class=\"pre\">high_pass</span></code> used during detection, and does not modify the stored <code class=\"docutils literal notranslate\"><span class=\"pre\">meanImg</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">max_proj</span></code>.</p>", "a[href=\"#proj-fig-hp\"]": "<figure class=\"align-default\" id=\"proj-fig-hp\">\n<a class=\"reference internal image-reference\" href=\"_images/02_spatial_hp_filter.png\"><img alt=\"Spatial HP Filter\" src=\"_images/02_spatial_hp_filter.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Effect of <code class=\"docutils literal notranslate\"><span class=\"pre\">spatial_hp_cp</span></code> values (0, 0.5, 1, 3) on the max projection. Higher values sharpen cell boundaries but may amplify noise.</span><a class=\"headerlink\" href=\"#proj-fig-hp\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#recommendations\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Recommendations<a class=\"headerlink\" href=\"#recommendations\" title=\"Link to this heading\">#</a></h2><p>If detection is poor:</p>", "a[href=\"#projection-images\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Projection Images<a class=\"headerlink\" href=\"#projection-images\" title=\"Link to this heading\">#</a></h1><p>Suite2p computes several reference images during registration and detection. These images are used for quality assessment and as inputs to Cellpose anatomical segmentation.</p>", "a[href=\"#proj-fig-anatomical\"]": "<figure class=\"align-default\" id=\"proj-fig-anatomical\">\n<a class=\"reference internal image-reference\" href=\"_images/01_anatomical_modes.png\"><img alt=\"Cellpose input images\" src=\"_images/01_anatomical_modes.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">The three Cellpose input images. <strong><code class=\"docutils literal notranslate\"><span class=\"pre\">meanImg</span></code></strong>: temporal mean. <strong><code class=\"docutils literal notranslate\"><span class=\"pre\">max_proj</span></code></strong>: maximum projection of the HP-filtered movie. <strong><code class=\"docutils literal notranslate\"><span class=\"pre\">max_proj</span> <span class=\"pre\">/</span> <span class=\"pre\">meanImg</span></code></strong> (default): log ratio highlights active regions.</span><a class=\"headerlink\" href=\"#proj-fig-anatomical\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
